@font-face {
  font-family: "SplitCJK";
  src: url("cjk-042.woff2") format("woff2");
  unicode-range: U+4E00-4E2F;
  font-display: optional;
}

new PerformanceObserver(function (list) {
  for (var e of list.getEntries()) if (e.duration > 50) count++;
}).observe({ type: "longtask", buffered: true });

var po = new PerformanceObserver(function (l) {
  l.getEntries().forEach(function (e) { frames++; });
});
try { po.observe({ type: "long-animation-frame", buffered: true }); } catch (e) {}

(function () {
  var t = localStorage.getItem("StackColorScheme") || "auto";
  var dark = matchMedia("(prefers-color-scheme: dark)").matches;
  document.documentElement.dataset.scheme =
    t === "dark" || (t === "auto" && dark) ? "dark" : "light";
})();

@media print {
  .left-sidebar, .right-sidebar { display: none; }
  body { background: #fff; color: #000; }
}

function add(doc, text) {
  for (var term of tokenize(text)) {
    if (!index[term]) index[term] = [];
    if (index[term].indexOf(doc) < 0) index[term].push(doc);
  }
}
